gcqi(){return"\u0648\u0627\u0628\u0633\u062a\u0647 \u0628\u0647 \u067e\u0644\u0646 \u0641\u0636\u0627\u06cc \u0630\u062e\u06cc\u0631\u0647\u200c\u0633\u0627\u0632\u06cc. \u0645\u06cc\u200c\u062a\u0648\u0627\u0646\u06cc\u062f \u0641\u0642\u0637 \u0628\u0631\u0627\u06cc \u0627\u06cc\u0646 \u0648\u06cc\u062c\u062a \u0628\u0628\u0646\u062f\u06cc\u062f\u061b \u0627\u06af\u0631 \u0631\u0648\u0634\u0646 \u0628\u0645\u0627\u0646\u062f\u060c \u0645\u062b\u0644 \u0633\u0627\u06cc\u0631 \u0648\u06cc\u062c\u062a\u200c\u0647\u0627\u0633\u062a."},
gcqh(){return"\u0627\u0644\u0627\u0646 \u062f\u0631 \u0633\u0637\u062d \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631 \u063a\u06cc\u0631\u0641\u0639\u0627\u0644 \u0627\u0633\u062a. \u0627\u0632 \u0645\u0633\u06cc\u0631 \xab\u0645\u062f\u06cc\u0631\u06cc\u062a \u0627\u0631\u062a\u0628\u0627\u0637\u0627\u062a \u2192 \u062a\u0646\u0638\u06cc\u0645\u0627\u062a CRM\xbb (\u06cc\u0627 \u0645\u0646\u0648\u06cc \u0645\u0631\u0628\u0648\u0637) \u06af\u0632\u06cc\u0646\u0647\u0654 \u0627\u0631\u0633\u0627\u0644 \u0641\u0627\u06cc\u0644 \u062f\u0631 \u0686\u062a \u0648\u0628 \u0631\u0627 \u0631\u0648\u0634\u0646 \u06a9\u0646\u06cc\u062f\u060c \u0628\u0639\u062f \u0628\u0631\u06af\u0631\u062f\u06cc\u062f \u0648 \u0627\u06cc\u0646 \u0633\u0648\u06cc\u06cc\u0686 \u0631\u0627 \u062a\u0646\u0638\u06cc\u0645 \u06a9\u0646\u06cc\u062f."},
gcqp(){return"\u0648\u06cc\u062c\u062a \u0641\u0639\u0627\u0644"},
gcqo(){return"\u0627\u06af\u0631 \u063a\u06cc\u0631\u0641\u0639\u0627\u0644 \u0634\u0648\u062f\u060c \u0628\u0627 \u0647\u0645\u06cc\u0646 \xab\u06a9\u0644\u06cc\u062f \u0639\u0645\u0648\u0645\u06cc\xbb \u0645\u06a9\u0627\u0644\u0645\u0647\u0654 \u062c\u062f\u06cc\u062f \u0634\u0631\u0648\u0639 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f (\u0648\u06cc\u062c\u062a\u200c\u0647\u0627\u06cc \u0642\u062f\u06cc\u0645 \u062f\u0631 \u067e\u0646\u0644 \u0628\u0627\u0642\u06cc \u0645\u06cc\u200c\u0645\u0627\u0646\u0646\u062f)."},
gcpS(){return"\u0644\u0637\u0641\u0627\u064b \xab\u0646\u0627\u0645 \u0648\u06cc\u062c\u062a\xbb \u0631\u0627 \u0648\u0627\u0631\u062f \u06a9\u0646\u06cc\u062f (\u0645\u062b\u0644\u0627\u064b \u0646\u0627\u0645 \u0633\u0627\u06cc\u062a \u06cc\u0627 \u0628\u062e\u0634)."},
gcpn(){return"\u0627\u06cc\u062c\u0627\u062f"},
gcq3(){return"\u0632\u0646\u062f\u0647 (WebSocket)"},
gcq6(){return"\u0646\u0638\u0631\u0633\u0646\u062c\u06cc"},
gcq5(){return"\u0642\u0637\u0639"},
gcq4(){return"\u0628\u062f\u0648\u0646 \u06a9\u0644\u06cc\u062f"},
gcpX(){return"\u0628\u0627\u0632\u062f\u06cc\u062f\u06a9\u0646\u0646\u062f\u0647 \u062f\u0631 \u062d\u0627\u0644 \u062a\u0627\u06cc\u067e \u0627\u0633\u062a\u2026"},
gcq8(){return"\u0627\u0631\u0633\u0627\u0644 \u0634\u062f"},
gcq7(){return"\u062e\u0648\u0627\u0646\u062f\u0647 \u0634\u062f"},
gcp9(){return"\u067e\u06cc\u0627\u0645 \u0635\u0648\u062a\u06cc \u062f\u0631 \u0686\u062a \u0648\u0628"},
gcp8(){return"\u067e\u06cc\u0627\u0645\u200c\u0647\u0627\u06cc \u0635\u0648\u062a\u06cc \u06a9\u0648\u062a\u0627\u0647 (\u0628\u0627\u0632\u062f\u06cc\u062f\u06a9\u0646\u0646\u062f\u0647 \u06cc\u0627 \u0627\u067e\u0631\u0627\u062a\u0648\u0631) \u0645\u0627\u0646\u0646\u062f \u0647\u0631 \u0641\u0627\u06cc\u0644 \u062f\u0631 \u0641\u0636\u0627\u06cc \u0630\u062e\u06cc\u0631\u0647\u200c\u0633\u0627\u0632\u06cc \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631 \u062d\u0633\u0627\u0628 \u0645\u06cc\u200c\u0634\u0648\u0646\u062f."},
gcqm(){return"\u067e\u06cc\u0627\u0645 \u0635\u0648\u062a\u06cc \u062a\u0648\u0633\u0637 \u0628\u0627\u0632\u062f\u06cc\u062f\u06a9\u0646\u0646\u062f\u0647\u0654 \u0633\u0627\u06cc\u062a"},
gbji(){return"\u0637\u0628\u0642 \u062a\u0646\u0638\u06cc\u0645\u0627\u062a \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631 \u0648 \u067e\u0644\u0646 \u0641\u0636\u0627. \u0645\u06cc\u200c\u062a\u0648\u0627\u0646\u06cc\u062f \u0641\u0642\u0637 \u0631\u0648\u06cc \u0647\u0645\u06cc\u0646 \u0648\u06cc\u062c\u062a \u063a\u06cc\u0631\u0641\u0639\u0627\u0644 \u06a9\u0646\u06cc\u062f."},
gbjh(){return"\u067e\u06cc\u0627\u0645 \u0635\u0648\u062a\u06cc \u062f\u0631 \u062a\u0646\u0638\u06cc\u0645\u0627\u062a CRM \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631 \u062e\u0627\u0645\u0648\u0634 \u0627\u0633\u062a \u06cc\u0627 \u062f\u0631 \u0627\u06cc\u0646 \u0648\u06cc\u062c\u062a \u0645\u062d\u062f\u0648\u062f \u0634\u062f\u0647 \u0627\u0633\u062a."},
gcqn(){return"\u067e\u06cc\u0627\u0645 \u0635\u0648\u062a\u06cc \u0628\u0631\u0627\u06cc \u0627\u06cc\u0646 \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631 \u062f\u0631 \u062a\u0646\u0638\u06cc\u0645\u0627\u062a CRM \u063a\u06cc\u0631\u0641\u0639\u0627\u0644 \u0627\u0633\u062a"},
gcpj(){return"\u0631\u0647\u0627 \u06a9\u0646\u06cc\u062f \u062a\u0627 \u0627\u0631\u0633\u0627\u0644 \u0634\u0648\u062f"},
gcpR(){return"\u0636\u0628\u0637 \u0635\u062f\u0627 \u062f\u0631 \u0645\u0631\u0648\u0631\u06af\u0631 \u0627\u06cc\u0646 \u0646\u0633\u062e\u0647 \u062f\u0631 \u062f\u0633\u062a \u0646\u06cc\u0633\u062a\u061b \u0627\u0632 \u0627\u067e \u06cc\u0627 \u062f\u06a9\u0645\u0647\u0654 \u067e\u06cc\u0648\u0633\u062a \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u06a9\u0646\u06cc\u062f"},
gcql(){return"\u0648\u06cc\u0633 \u0645\u0647\u0645\u0627\u0646 \u062e\u0627\u0645\u0648\u0634"},
gc6x(){return"\u0638\u0627\u0647\u0631 \u0628\u0631\u0646\u0627\u0645\u0647"},
gc6w(){return"\u0646\u062d\u0648\u0647\u0654 \u0646\u0645\u0627\u06cc\u0634 \u067e\u0646\u0644 \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631 \u062f\u0631 \u062f\u0633\u06a9\u062a\u0627\u067e (\u0635\u0641\u062d\u0647\u0654 \u0648\u0627\u062d\u062f \u06cc\u0627 \u0686\u0646\u062f \u062a\u0628)"},
gbfD(){return"\u062a\u0646\u0638\u06cc\u0645\u0627\u062a \u0638\u0627\u0647\u0631\u06cc"},
gce_(){return"\u067e\u0646\u0644 \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631 (\u062f\u0633\u06a9\u062a\u0627\u067e)"},
gce1(){return"\u0635\u0641\u062d\u0647\u0654 \u0648\u0627\u062d\u062f"},
gce2(){return"\u062f\u0631 \u0647\u0631 \u0632\u0645\u0627\u0646 \u0641\u0642\u0637 \u06cc\u06a9 \u0635\u0641\u062d\u0647 \u0628\u0627\u0632 \u0627\u0633\u062a (\u0646\u0627\u0648\u0628\u0631\u06cc \u06a9\u0644\u0627\u0633\u06cc\u06a9)"},
gce3(){return"\u062a\u0628 \u062f\u0631 \u0646\u0648\u0627\u0631 \u0628\u0627\u0644\u0627"},
gce4(){return"\u0686\u0646\u062f \u0635\u0641\u062d\u0647 \u0628\u0627\u0632 \u0628\u0645\u0627\u0646\u062f \u0648 \u0628\u0627 \u062a\u0628\u200c\u0647\u0627\u06cc \u0646\u0648\u0627\u0631 \u062a\u06cc\u0631\u0647 \u0628\u0627\u0644\u0627\u06cc \u067e\u0646\u0644 \u062c\u0627\u0628\u0647\u200c\u062c\u0627 \u0634\u0648\u06cc\u062f (\u0641\u0642\u0637 \u062f\u0633\u06a9\u062a\u0627\u067e). \u062a\u0628\u200c\u0647\u0627\u06cc \u067e\u0633\u200c\u0632\u0645\u06cc\u0646\u0647 \u062f\u0631 \u062d\u0627\u0641\u0638\u0647 \u0645\u06cc\u200c\u0645\u0627\u0646\u0646\u062f\u061b \u06a9\u0644\u06cc\u062f \u067e\u0627\u06cc\u062f\u0627\u0631 \u0645\u0633\u06cc\u0631 \u0628\u0631\u0627\u06cc \u0628\u0627\u0632\u06af\u0634\u062a \u0628\u0647\u062a\u0631 \u0628\u0647 \u0647\u0645\u0627\u0646 \u062a\u0628 \u0647\u0645\u200c\u0633\u0648 \u0628\u0627 \u0631\u0648\u062a\u0631 \u0627\u0633\u062a."},
gce0(){return"\u062d\u0627\u0644\u062a \u062a\u0628 \u0641\u0642\u0637 \u062f\u0631 \u0639\u0631\u0636 \u0632\u06cc\u0627\u062f \u0627\u0639\u0645\u0627\u0644 \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u062f\u0631 \u0645\u0648\u0628\u0627\u06cc\u0644 \u0647\u0645\u06cc\u0634\u0647 \u062d\u0627\u0644\u062a \u062a\u06a9\u200c\u0635\u0641\u062d\u0647 \u0627\u0633\u062a."},
gce7(){return"\u0630\u062e\u06cc\u0631\u0647 \u0634\u062f"},
gce6(){return"\u0630\u062e\u06cc\u0631\u0647\u0654 \u062a\u0646\u0638\u06cc\u0645\u0627\u062a \u0646\u0627\u0645\u0648\u0641\u0642 \u0628\u0648\u062f"},
gce5(){return"\u0630\u062e\u06cc\u0631\u0647"},
gciV(){return"\u0628\u0633\u062a\u0646 \u0627\u06cc\u0646 \u062a\u0628"},
