gciZ(){return"\u062a\u0628 \u067e\u06cc\u0646\u200c\u0634\u062f\u0647"},
gciY(){return"\u0627\u06cc\u0646 \u062a\u0628 \u067e\u06cc\u0646 \u0634\u062f\u0647 \u0627\u0633\u062a. \u0628\u0627 \u0628\u0633\u062a\u0646\u060c \u0627\u0632 \u0646\u0648\u0627\u0631 \u062a\u0628\u200c\u0647\u0627 \u062d\u0630\u0641 \u0645\u06cc\u200c\u0634\u0648\u062f. \u0622\u06cc\u0627 \u0645\u0637\u0645\u0626\u0646 \u0647\u0633\u062a\u06cc\u062f\u061f"},
