gceb(){return"\u0631\u0641\u062a\u0646 \u0628\u0647 \u062a\u0628 \u0645\u0648\u062c\u0648\u062f \u06cc\u0627 \u0628\u0627\u0632 \u06a9\u0631\u062f\u0646 \u062a\u0628 \u062c\u062f\u06cc\u062f"},
