cSg(a){return"\u0648\u06cc\u062c\u062a \u0646\u0627\u0634\u0646\u0627\u062e\u062a\u0647: "+a},
gcSi(){return"\u0627\u06cc\u0646 \u0648\u06cc\u062c\u062a \u062b\u0628\u062a \u0646\u0634\u062f\u0647 \u0627\u0633\u062a"},
gcS3(){return"\u0627\u0641\u0632\u0627\u06cc\u0634 \u0639\u0631\u0636"},
gcRZ(){return"\u06a9\u0627\u0647\u0634 \u0639\u0631\u0636"},
gcSa(){return"\u0628\u0627\u0644\u0627"},
gcS9(){return"\u067e\u0627\u06cc\u06cc\u0646"},
gcS2(){return"\u067e\u0646\u0647\u0627\u0646 \u06a9\u0631\u062f\u0646"},
gcS6(){return"\u062e\u0648\u0627\u0646\u062f\u0647 \u0634\u062f"},
gcS7(){return"\u0628\u0647\u200c\u0639\u0646\u0648\u0627\u0646 \u062e\u0648\u0627\u0646\u062f\u0647\u200c\u0634\u062f\u0647 \u0639\u0644\u0627\u0645\u062a \u062e\u0648\u0631\u062f"},
